        [400573] = "Blasts the target with energy, dealing Arcane damage. Each time you cast Arcane Blast, the damage of all other spells is increased by $400573s1% and mana cost of Arcane Blast is increased by $400573s2%. Effect stacks up to $400573u times and lasts $400573d.",
        [400574] = "Blasts the target with energy, dealing $s1 Arcane damage. Each time you cast Arcane Blast, the damage of all your other spells is increased by $400573s1% and the mana cost of Arcane Blast is increased by $400573s2%. Effect stacks up to $400573u times and lasts $400573d or until any other damage spell is cast.",
        [400586] = "Blasts the target with energy, dealing Arcane damage.  Each time you cast Arcane Blast, the damage of all other Arcane spells is increased by $400573s1% and mana cost of Arcane Blast is increased by $400573s2%.  Effect stacks up to $400573u times and lasts $400573d.",
        [400588] = "Gives your Arcane Blast spell a $m1% chance, and your Fireball, Frostbolt, and Frostfire Bolt spells a ${$m1/2}% chance to reduce the channeled duration of your next Arcane Missiles spell by $400589s1%, reduce the Mana cost by $400589s3%, and missiles fire every ${$m2/10}.1 sec.",
        [400589] = "Gives your Arcane Blast, Fireball, and Frostbolt spells a chance to reduce the channeled duration of the next Arcane Missiles spell by $400589s1%, reduce the mana cost by $s3%, and missiles fire every ${$400588m2/10}.1 sec.",
        [400610] = "Launches several missiles at the enemy target, causing ${$<power>*$m1/100} to ${$<power>*$M1/100} Arcane damage. This spell also has a ${$400588h/2}% to trigger Missile Barrage.",
        [400613] = "The target becomes a Living Bomb, taking ${$<power>*$400613m1/100*4} Fire damage over $d.  After $d or when the spell is dispelled, the target explodes dealing ${$<power>*$400614m1/100} Fire damage to all enemies within $400614a1 yards.\r\n\r\nLiving Bomb benefits from all talents and effects that trigger from or modify Scorch.",
        [400614] = "The target becomes a Living Bomb, taking ${$<power>*$400613m1/100*4} Fire damage over $d.  After $d or when the spell is dispelled, the target explodes dealing ${$<power>*$400614m1/100} Fire damage to all enemies within $400614a1 yards.",
        [400615] = "Fire Blast will always deal a critical strike, can be cast while casting another spell, and is not affected by the global cooldown, but its cooldown is increased to $s9 sec.",
        [400616] = "Blasts the enemy for $s1 Fire damage.",
        [400618] = "Blasts the enemy for $s1 Fire damage.",
        [400619] = "Blasts the enemy for $s1 Fire damage.",
        [400620] = "Blasts the enemy for $s1 Fire damage.",
        [400621] = "Blasts the enemy for $s1 Fire damage.",
        [400622] = "Blasts the enemy for $s1 Fire damage.",
        [400623] = "Blasts the enemy for $s1 Fire damage.",
        [400624] = "Your non-periodic critical strikes with Fireball, Frostfire Bolt, Fire Blast, and Scorch grant Hot Streak for $400625d. Hot Streak reduces the cast time of Pyroblast by $400625s1%, stacking up to $400625s2 times.",
        [400625] = "Your non-periodic critical strikes with Fireball, Frostfire Bolt, Fire Blast, and Scorch grant Hot Streak for $400625d. Hot Streak reduces the cast time of Pyroblast by $400625s1%, stacking up to $400625s2 times.\r\n",
        [400640] = "Deals $s1 Frost damage to an enemy target. Deals $s2% increased damage to Frozen targets.",
        [400647] = "Gives your Chill effects a $s2% chance to grant you the Fingers of Frost effect, which treats your next $m1 $lspell:spells; cast as if the target were Frozen. Lasts $400669d.",
        [400669] = "Gives your Chill effects a chance to grant you the Fingers of Frost effect, which treats your next spells cast as if the target were Frozen.  Lasts $d.",
        [400670] = "Gives your Chill effects a chance to grant you the Fingers of Frost effect, which treats your next spells cast as if the target were Frozen.  Lasts $d.",
        [400730] = "Your next Fireball, Spellfrost Bolt, Balefire Bolt, or Frostfire Bolt spell is instant and costs no mana.",
        [400731] = "Your Frost damage spells with chilling effects have a $h% chance to cause your next Fireball, Spellfrost Bolt, Balefire Bolt, or Frostfire Bolt spell to be instant cast and cost no mana.",
        [400735] = "Records the subject's space-time position. $s4% of all Arcane damage done by the caster will be converted to chronomantic healing on each of the caster's current Temporal Beacon targets. This healing is reduced by $s5% on self, and also reduced by $s6% when damage is done by Arcane spells that damage multiple targets.",
        [401417] = "Heals the target for ${$<healpower>*$m1/100*3} health over $d and applies Temporal Beacon for $400735s3 sec. \r\n\r\nTemporal Beacon\r\n$@spellicon400735\r\n$@spelldesc400735",
        [401460] = "Heals the target for ${$<healpower>*$m1/100*3} health over $d and applies Temporal Beacon for ${$400735m3*2/3} sec.\r\n\r\n$@spellicon400735\r\n$@spelldesc400735",
        [401462] = "Your current target with your Temporal Beacon instantly heals all damage taken over the last $s1 seconds. Ineffective on targets that did not have a Temporal Beacon $s1 seconds ago.",
        [401488] = "Engrave your pants with the Shadowstrike rune:\r\n\r\n$@spellicon399985\r\n$@spelldesc399985",
        [401502] = "Launches a bolt of frostfire at the enemy, causing $s2 Frostfire damage, slowing movement speed by $s1% and causing an additional $o3 Frostfire damage over $d. This spell will be checked against the lower of the target's Frost and Fire resists and counts as both Frost and Fire damage.",
        [401556] = "Summons a spellfire flame that moves toward the target, leaving a trail of spellfire. This trail deals ${$<power>*$401558m1/100} Spellfire damage every second to nearby enemies. Lasts $d.",
        [401558] = "Deals ${$<power>*$m1/100} Fire damage every $t1 sec.",
