        [401847] = "Combine with 3 other pieces to make the full map.",
        [401859] = "Places a spell on the target that heals them for ${($m1+($bh*$bc))*$<mult>} the next time they take damage or receive non-periodic healing. When the heal occurs, Prayer of Mending jumps to a party or raid member within $401880a1 yards. Jumps up to $s2 times and lasts $401877d after each jump. This spell can only be placed on one target at a time per caster.",
        [401863] = "Places a spell on the target that heals them the next time they take damage.  When the heal occurs, Prayer of Mending jumps to a party or raid member within $41635a1 yards. Jumps up to $48113n times and lasts $48111d after each jump. This spell can only be placed on one target at a time.\r\n",
        [401877] = "Places a spell on the target that heals them the next time they take damage or receive healing.  When the heal occurs, Prayer of Mending jumps to a party or raid member within $a1 yards.  Jumps up to $n times and lasts $d after each jump.  This spell can only be placed on one target at a time.",
        [401937] = "Heals a friendly target and the caster for $s1. Low threat.",
        [401946] = "Heals all of target player's party members within $a1 yards of target player for ${$<healpower>*$m1/100} to ${$<healpower>*$M1/100}.",
        [401955] = "A word of dark binding that inflicts ${$<damagepower>*$m1/100} to ${$<damagepower>*$M1/100} Shadow damage to the target.  If the target is not killed by Shadow Word: Death, the caster takes damage equal to $m2% of the damage attempted against the target.",
        [401962] = "A word of dark binding that inflicts Shadow damage to the target.  If the target is not killed by Shadow Word: Death, the caster takes damage equal to the damage inflicted upon the target.",
        [401969] = "Your Shadow Word: Pain now also afflicts up to ${$m1-1} additional nearby targets within $s2 yards.",
        [401977] = "Creates a shadowy fiend to attack the target.  Caster receives $401988s1% mana when the Shadowfiend attacks. Lasts $d.",
        [401984] = "The Shadowfiend's melee attacks siphon energy from the target, converting it into mana for its master.",
        [401988] = "The Shadowfiend's melee attacks siphon energy from the target, converting it into mana for its master.",
        [401990] = "Crawls through the shadows to the target enemy, and increases damage done by the Shadowfiend by $s2% for $d.",
        [402000] = "Reduces the cooldown on your Power Word: Shield spell by ${$m1/-1000} sec and reduces its mana cost by $s2%.",
        [402004] = "Instantly reduces all damage taken by a friendly target by $s1% and increases resistance to Dispel mechanics by $s2% for $d.",
        [402010] = "Transformed back into its normal form.",
        [402174] = "Launches a volley of holy light at the target, causing $402284s1 Holy damage to an enemy, or $402289s1 healing to an ally, instantly and every $402261t2 sec for $402261d.",
        [402261] = "Deals Holy damage every $t2 sec.",
        [402277] = "Healing every $t2 sec for $d.",
        [402284] = "Dealing $s1 Holy damage every $402261t2 sec.",
        [402289] = "Healing for $s1 every $402277t2 sec. for $402277d.",
        [402308] = "Decipher the spell notes with a Comprehension Charm to learn a new Engraving spell.",
        [402311] = "Decipher the spell notes with a Comprehension Charm to learn a new Engraving spell.",
        [402319] = "Combine 6 Azora Apprentice Notes to create a new engraving recipe.",
        [402668] = "Applies your Vampiric Embrace talent to your target, causes ${$<damagepower>*$m2/100*5} Shadow damage over $d to your target, and causes all party members to gain mana equal to $s1% of any Shadow spell damage you deal to the target.",
        [402779] = "$s1% of Shadow spell damage taken restores mana to the Priest's party.",
        [402789] = "Call an eye of the void to fight for you for $d. The eye can cast a variety of curses on your target.",
        [402790] = "Hurls a bolt of dark magic at an enemy, inflicting Shadow damage.",
        [402791] = "Curses the target for $d, reducing Shadow and Arcane resistances by $s1 and increasing Shadow and Arcane damage taken by $s2%.  Only one Curse per Warlock can be active on any one target.",
        [402792] = "Curses the target for $d, reducing Fire and Frost resistances by $s1 and increasing Fire and Frost damage taken by $s2%.  Only one Curse per Warlock can be active on any one target.",
        [402794] = "Forces the target to speak in Demonic, slowing the casting time of all spells by $s1%.  Only one Curse per Warlock can be active on any one target.  Lasts $d.",
        [402799] = "Break off splinters of your soul to animate $s1 miniature copies of yourself that attempt to attack your current target with a mace, sword, and axe, reducing the attack speed, attack power, and armor respectively of any target they hit.",
        [402801] = "Animate $s1 skeletons that attack your current target with a mace, sword, and axe, reducing the target's attack speed, attack power, and armor respectively.",
        [402802] = "Animate $s1 skeletons that attack your current target with a mace, sword, and axe, reducing the target's attack speed, attack power, and armor respectively.",
        [402808] = "Increases the time between an enemy's attacks by $s1%. Lasts $d.",
        [402811] = "Reduces the target's Attack Power by $s1. Lasts $d.",
        [402818] = "Reduces an enemy's armor by $s1. Lasts $d.",
