        [409337] = "For the next $409324d, $409324s1% of your damage is converted to healing on up to 3 nearby party members, and $409324s2% of your healing is converted to damage on your most recent Flame Shock target.",
        [409368] = "Your pet's damage and health are increased by $s1%, and its Focus regeneration by $s3%. In addition, your pet's Growl now also Taunts the target to attack it for $409372d.",
        [409372] = "Taunts the target to attack you, but has no effect if the target is already attacking you.",
        [409379] = "Give the command to kill, increasing your pet's damage done from Claw and Bite by ${$409396M1*3}% for $409396d.  Each Claw or Bite done by the pet reduces the damage bonus by $409396s1%.",
        [409396] = "Give the command to kill, increasing your pet's damage done from Claw and Bite by ${$409396M1*3}% for $409396d.  Each Claw or Bite done by the pet reduces the damage bonus by $409396s1%.",
        [409418] = "Give the command to kill, increasing your pet's damage from Claw and Bite by ${$409396M1*3}% for $409396d.  Each Claw or Bite done by the pet reduces the damage bonus by $409396s1%.",
        [409428] = "Increases your critical strike chance by $s1%, and reduces the Mana cost of all your Shot abilities by $s2%.",
        [409433] = "You deal $409433s3% weapon damage, refreshing the current Sting on your target and triggering an effect:\r\n\r\nSerpent Sting - Instantly deals $409493s1% of the damage done by your Serpent Sting.\r\n\r\nViper Sting - Instantly restores mana to you equal to $409494s1% of the total amount drained by your Viper Sting.\r\n\r\nScorpid Sting - Attempts to Disarm the target for $409495d. This effect cannot occur more than once per 1 minute.",
        [409493] = "You deal $409433s3% weapon damage, refreshing the current Sting on your target and triggering an effect:\r\n\r\nSerpent Sting - Instantly deals $409493s1% of the damage done by your Serpent Sting.\r\n\r\nViper Sting - Instantly restores mana to you equal to $409494s1% of the total amount drained by your Viper Sting.\r\n\r\nScorpid Sting - Attempts to Disarm the target for $409495d. This effect cannot occur more than once per 1 minute.",
        [409494] = "You deal $409433s3% weapon damage, refreshing the current Sting on your target and triggering an effect:\r\n\r\nSerpent Sting - Instantly deals $409493s1% of the damage done by your Serpent Sting.\r\n\r\nViper Sting - Instantly restores mana to you equal to $409494s1% of the total amount drained by your Viper Sting.\r\n\r\nScorpid Sting - Attempts to Disarm the target for $409495d. This effect cannot occur more than once per 1 minute.",
        [409495] = "You deal $409433s3% weapon damage, refreshing the current Sting on your target and triggering an effect:\r\n\r\nSerpent Sting - Instantly deals $409493s1% of the damage done by your Serpent Sting.\r\n\r\nViper Sting - Instantly restores mana to you equal to $409494s1% of the total amount drained by your Viper Sting.\r\n\r\nScorpid Sting - Attempts to Disarm the target for $409495d. This effect cannot occur more than once per 1 minute.",
        [409504] = "Your melee and ranged criticals increase your attack power by $409507s1% of your current Agility for $409507d.",
        [409507] = "Your ranged criticals increase your attack power by $409507s1% of your Agility for $409507d.",
        [409580] = "The hunter invokes the heart of a lion, increasing total stats by $409583s1% and Attack Power by $409583s2 for all nearby allies, and increasing total stats for the Hunter by an additional $409580s1%.",
        [409583] = "The hunter invokes the heart of a lion, increasing total stats by $409583s1% for all nearby allies, and increasing total stats for the Hunter by an additional $409580s1%.",
