        [428845] = "Add $q2 Lesser Magic Wands to complete the shipment.",
        [428846] = "Add $q2 Minor Wizard Oil to complete the shipment.",
        [428847] = "Add $q2 Rough Copper Bombs to complete the shipment.",
        [428848] = "Add $q2 Rough Boomsticks to complete the shipment.",
        [428849] = "Add $q2 Handstitched Leather Belts to complete the shipment.",
        [428850] = "Add $q2 Embossed Leather Vests to complete the shipment.",
        [428851] = "Add $q2 Brown Linen Pants to complete the shipment.",
