        [428857] = "Add $q2 Brilliant Smallfish to complete the shipment.",
        [428858] = "Add $q2 Heavy Linen Bandages to complete the shipment.",
        [428861] = "Teleports back to where you last cast Blink from and resets the cooldown on Blink. Only usable within $428865d of casting Blink.",
        [428863] = "Gain the Displacement ability:\r\n\r\n$@spellicon428861\r\n$@spelldesc428861",
        [428878] = "Unleash a reality-distorting burst of raw magic at your enemy, dealing ${$<power>*$m1/100} to ${$<power>*$M1/100} Chimeric damage.\r\n\r\nIncreasing your Balefire Bolt and Pyroblast damage by $s3%, decreasing your Spirit by $s2%, and stacking up to $u times for $d. If your Spirit reaches 0, you die.\r\n\r\nThis spell will be checked against the lower of the target's Arcane, Fire, and Frost resists.",
        [428885] = "Launches an orb of temporal energy which slowly moves forward and every $428888t1 sec grants all nearby party members a shield absorbing ${$428895m1*$<power>/100} damage for $428895d. This shield accumulates additional value if party members remain near the orb.",
        [428909] = "Your Holy Light spell reduces the cast time of your next Holy Light spell by ${$428912m1/-1000}.1 sec. Lasts $428912d.",
        [428912] = "\r\n\r\n",
        [429125] = "Hastens your spellcasting, increasing spell casting speed by $s1% and reduces the pushback suffered from damaging attacks while casting by $s2%.  Lasts $d.",
        [429133] = "Increases the damage prevented by your Blessing of Sanctuary by $s1%, and increases damage done by your Blessing of Sanctuary by $s2% of your shield block value.",
        [429139] = "Your Consecration damage can now be critical strikes, and damage from your Exorcism, Holy Shock, Sunlight, Holy Wrath, and Consecration spells gains additional critical strike chance equal to your melee critical strike chance.",
        [429142] = "Increases your critical strike chance with spells by $s1%. In addition, your critical healing spells heal the target for $s2% of the healed amount over $426162d.",
        [429144] = "Reduces the mana cost of your Cleanse and Purify spells by $m1% and reduces the cooldown of your Exorcism and Holy Wrath spells by $m2%.",
        [429145] = "Sends bolts of holy power in all directions, causing $s1 Holy damage to all targets within $a1 yds and Stunning Demon and Undead targets for $429147d.",
        [429146] = "Sends bolts of holy power in all directions, causing $s1 Holy damage to all targets within $a1 yds and Stunning Demon and Undead targets for $429147d.",
